def minimumSum(S):
    n = len(S)
    if n == 1:
        return 0

    # Create a list to store the characters after replacing '?'
    result = list(S)

    # Try to form a palindrome by replacing '?'
    for i in range(n // 2):
        left = i
        right = n - 1 - i

        if S[left] == '?' and S[right] == '?':
            result[left] = result[right] = 'a'
        elif S[left] == '?':
            result[left] = result[right]
        elif S[right] == '?':
            result[right] = result[left]
        elif S[left] != S[right]:
            return -1

    # Check if the resulting string is a palindrome
    for i in range(n // 2):
        if result[i] != result[n - 1 - i]:
            return -1

    # Calculate the sum of differences of adjacent characters
    total_sum = 0
    for i in range(1, n):
        total_sum += abs(ord(result[i]) - ord(result[i - 1]))

    return total_sum

